import {dateFields,readDates} from './schedule-ui.js';
import {methods,methodDefaults,methodName,hasPhases,hasSprints,sprintPhase,phases} from './work-methods.js';
import {libraryIcon} from './agent-appearance.js';
import {proseMarkdown} from './rich-text.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(a,text)=>`<button type="button" data-work="${a}">${text}</button>`;
const area=(key,label,value,rows=2)=>`<label>${label}<textarea name="${key}" rows="${rows}" maxlength="8000">${esc(value)}</textarea></label>`;
function prose(text=''){
  return `<div class="work-delivery-prose rendered-markdown">${proseMarkdown(text)}</div>`;
}
const documentNote=(label,text)=>`<section class="work-document-section"><h4 class="work-section-heading">${esc(label)}</h4><div class="markdown document-markdown">${proseMarkdown(text)}</div></section>`;
const note=(label,text)=>`<div class="work-delivery-note"><h4>${label}</h4>${prose(text)}</div>`;
const disclosure=(title,body,{open=false,extra='',className=''}={})=>`<details class="work-delivery-disclosure ${className}" ${open?'open':''}><summary>${libraryIcon('chevron-right',16)}<span>${esc(title)}</span>${extra}</summary><div class="work-disclosure-body">${body}</div></details>`;
const sprintHistory=s=>disclosure(s.name,
  note('Sprint goal',s.goal)+note('Review',s.review)+note('Next improvement',s.improvement),
  {className:'work-sprint-history',extra:`<span class="work-sprint-score">${libraryIcon('circle-check',14)} ${s.donePoints} / ${s.items.reduce((n,t)=>n+t.points,0)} <span>verified points</span></span>`});

const reviewerFields=(board,ids,selected=[],qaLeadId=null)=>`<fieldset class="work-dependencies"><legend>Delegated reviewers</legend>${ids.filter(id=>id!==qaLeadId).map(id=>`<label><input type="checkbox" name="reviewerIds" value="${esc(id)}" ${selected.includes(id)?'checked':''}>${esc(board.actor(id).role||board.actor(id).title||id)}</label>`).join('')||'<p>No additional teammates available.</p>'}</fieldset>`;

export function methodFields(board){
  const m=board.draft.management||methodDefaults();
  return `<div class="work-form-section work-method-section"><div class="work-step"><span>4</span><div><h3>How should the project run?</h3><p>Choose a delivery approach. Your task-change approval choice still applies.</p></div></div><fieldset class="work-method-options"><legend>Project management style</legend>${Object.entries(methods).map(([id,meta])=>`<label class="work-method-choice" data-method="${id}"><input type="radio" name="method" value="${id}" ${m.method===id?'checked':''}><span>${libraryIcon(({scrum:'rotate-ccw',kanban:'list-checks'})[id]||meta.icon,18)}<strong>${meta.name}</strong><small>${meta.description}</small></span></label>`).join('')}</fieldset>${area('managementGoal','Product / delivery goal',m.goal)}${area('methodReason','Why this approach? <small>optional · recorded with the brief</small>',m.reason)}<div class="work-method-settings">${hasSprints(m)?`<div class="work-form-pair"><label>Sprint capacity <small>story points per cycle</small><input name="sprintCapacity" type="number" min="1" max="200" value="${m.sprintCapacity}"></label><label>Team sync cadence<input name="syncCadence" maxlength="300" value="${esc(m.syncCadence)}"></label></div><p class="work-note">Refine the backlog, then select ready tasks and a Sprint Goal in Delivery. Estimates freeze during a sprint; unfinished work returns to the backlog. You start and close sprints. This sync description guides the team. Set automatic check-ins separately under Dates & reminders.</p>`:''}${m.method==='kanban'?`<label>Work-in-progress limit<input name="wipLimit" type="number" min="1" max="100" value="${m.wipLimit}"></label><p class="work-note">A shared cap on In progress, Blocked, and Needs Review tasks. Finish work before pulling more.</p>`:''}${hasPhases(m)?`<p class="work-note">Requirements → Design → Implementation → Testing → Deployment → Maintenance. You approve each gate with evidence. Record the three baselines before the Requirements gate. After that gate, scope and assignment changes require your review, including in autonomous mode.</p>${area('scopeBaseline','Scope baseline <small>can be completed at the first gate</small>',m.scopeBaseline)}${area('scheduleBaseline','Schedule baseline <small>dependencies and cycles, not invented hours</small>',m.scheduleBaseline)}${area('riskRegister','Risk register <small>risk, owner, impact, response</small>',m.riskRegister)}`:''}</div><details class="work-method-roles"><summary>Delivery roles & Definition of Done</summary><p class="work-note">Unassigned roles stay with you. The Scrum Master facilitates; the Product Owner controls priorities. QA must not verify its own work.</p><div class="work-role-grid">${[['processLeadId',hasSprints(m)?'Scrum Master / process lead':'Process lead'],['productOwnerId','Product Owner'],['qaLeadId','QA lead']].map(([key,label])=>`<label>${label}<select name="${key}">${board.options(board.draft.participantIds,m[key],key==='qaLeadId'?'Independent teammate / you':'You')}</select></label>`).join('')}</div>${reviewerFields(board,board.draft.participantIds,m.reviewerIds||[],m.qaLeadId)}${button('profiles',libraryIcon('compass',15)+' Scrum Master profile & agent settings')}${area('definitionOfDone','Definition of Done',m.definitionOfDone,4)}</details><p class="work-note">Completion requires independent verification with evidence. Method rules and roles travel with the JSON and Markdown brief.</p></div>`;
}
export function readMethod(form,previous){
  const d=Object.fromEntries(new FormData(form));if(!d.method)return previous||null;const m={...methodDefaults(d.method),...previous,method:d.method};
  for(const [field,key] of [['managementGoal','goal'],['methodReason','reason'],['definitionOfDone','definitionOfDone'],['scopeBaseline','scopeBaseline'],['scheduleBaseline','scheduleBaseline'],['riskRegister','riskRegister'],['syncCadence','syncCadence']])if(d[field]!==undefined)m[key]=d[field];
  for(const key of ['processLeadId','productOwnerId','qaLeadId'])m[key]=d[key]||null;
  m.reviewerIds=[...form.querySelectorAll('[name=reviewerIds]:checked')].map(input=>input.value);
  for(const key of ['sprintCapacity','wipLimit'])if(d[key]!==undefined)m[key]=Number(d[key]);return m;
}
export function deliveryHTML(board,p){
  const m=p.management,f=p.flow;if(!m)return '<p class="work-list-empty">This existing brief keeps its original workflow. Choose a delivery method when creating your next task or plan.</p>';
  const sprint=f.sprints.find(s=>s.id===f.activeSprintId),editable=p.status==='active';
  return `<div class="work-method-detail"><div class="work-method-heading"><span class="availability-badge global">${esc(methodName(m))}</span><h3>${esc(m.goal||p.title)}</h3><p>${esc(methods[m.method].description)}</p></div><div class="work-delivery-roles">${[['processLeadId','Process lead'],['productOwnerId','Product Owner'],['qaLeadId','QA lead']].map(([key,label])=>`<div><small>${label}</small>${m[key]?board.owner(m[key]):'<strong>'+ (key==='qaLeadId'?'Independent teammate / you':'You')+'</strong>'}</div>`).join('')}</div><section class="work-review-delegation"><h3>Task reviewers</h3><p>${m.qaLeadId?'The QA lead and delegated reviewers can verify tasks.':'Independent teammates can verify tasks.'} Owners and contributors cannot verify their own work. Final acceptance stays with you.</p><div class="work-reviewer-list">${(m.reviewerIds||[]).map(id=>board.owner(id)).join('')||'<span class="work-note">No delegated reviewers</span>'}</div>${editable?button('reviewers','Manage reviewers'):''}</section>${hasPhases(m)?`<section><h3>Phase gates</h3><ol class="work-phase-track">${phases.map((phase,i)=>`<li class="${i<f.phaseIndex?'is-done':i===f.phaseIndex?'is-current':''}">${libraryIcon(i<f.phaseIndex?'circle-check':'circle',15)}${phase}</li>`).join('')}</ol>${f.phaseIndex<phases.length&&editable?button('gate','Review '+phases[f.phaseIndex]+' gate'):''}${f.gates.map(g=>`<details><summary>${esc(g.phase)} · Approved</summary><p>${esc(g.evidence)}</p></details>`).join('')}</section>`:''}${hasSprints(m)?`<section class="work-sprint"><div><h3>${sprint?esc(sprint.name):'Sprint planning'}</h3><span>${m.sprintCapacity} point capacity</span></div>${sprint?`<strong>${esc(sprint.goal)}</strong><p>${sprint.schedule?.start||sprint.schedule?.due?`Planned window: ${esc(sprint.schedule.start||'Open start')} → ${esc(sprint.schedule.due||'Open end')} · ${esc(p.reminders.timeZone)}`:'No planned dates yet'} · Sprint closure requires your review.</p><p>${sprint.items.reduce((n,t)=>n+t.points,0)} points committed · ${sprint.items.filter(t=>p.items.find(i=>i.id===t.id)?.status==='done').length}/${sprint.items.length} verified tasks</p><ul>${sprint.items.map(t=>`<li>${esc(p.items.find(i=>i.id===t.id)?.title)} <span>${t.points} pts</span></li>`).join('')}</ul>${editable?button('close-sprint','Review & close sprint'):''}`:`<p>Choose ready backlog items with an owner, acceptance criteria, and an estimate of 1–8 points.</p>${editable&&sprintPhase(m,f)?button('start-sprint','Plan a sprint'):''}`}<small>Sync: ${esc(m.syncCadence)}</small></section>${f.sprints.filter(s=>s.status==='closed').map(sprintHistory).join('')}`:''}${m.method==='kanban'?`<section class="work-wip"><h3>Work in progress</h3><strong>${p.items.filter(t=>['in_progress','blocked','needs_review'].includes(t.status)).length} / ${m.wipLimit}</strong><p>Blocked and review items stay counted. Finish before starting.</p></section>`:''}${disclosure('Definition of Done',prose(m.definitionOfDone),{open:true})}${disclosure('Operating protocol & decision',note('Protocol',m.protocol)+note('Decision',m.reason||'Method selected by sponsor.')+note('Controls',m.controls)+(hasPhases(m)?note('Scope baseline',m.scopeBaseline||'Pending')+note('Schedule baseline',m.scheduleBaseline||'Pending')+note('Risk register',m.riskRegister||'Pending'):''))}</div>`;
}
export function taskMethodFields(p,t){return !p.management?'':`<div class="work-form-pair">${hasSprints(p.management)?`<label>Story points<select name="points"><option value="">Not estimated</option>${[1,2,3,5,8,13,20].map(n=>`<option value="${n}" ${t.points===n?'selected':''}>${n}${n>8?' · split before sprint':''}</option>`).join('')}</select></label>`:''}${hasPhases(p.management)?`<label>Delivery phase<select name="phase">${phases.map(phase=>`<option ${phase===(t.phase||phases[p.flow.phaseIndex])?'selected':''}>${phase}</option>`).join('')}</select></label>`:''}</div>${area('acceptance','Task acceptance criteria',t.acceptance)}${t.sprintId===p.flow.activeSprintId&&t.sprintId?'<p class="work-note">Sprint scope and estimates are frozen until the sprint closes.</p>':''}${t.verification?`<div class="work-brief-document">${documentNote(`${t.verification.passed?'Verified':'Changes requested'} by ${t.verification.name}`,t.verification.evidence)}</div>`:''}`;}

export function flowDialog(board,action){
  const p=board.detail,m=p.management,f=p.flow;
  if(action==='start_sprint'){
    const ready=p.items.filter(t=>t.status==='todo'&&t.ownerId&&t.acceptance?.trim()&&[1,2,3,5,8].includes(t.points)&&(!hasPhases(m)||t.phase===phases[f.phaseIndex]));
    board.dialogShell('Plan a sprint',`<form class="work-item-form"><label>Sprint Goal<input name="goal" required maxlength="1000" placeholder="One usable outcome for this sprint"></label>${dateFields({},p.reminders.timeZone,{milestone:false})}<p>Capacity: ${m.sprintCapacity} points. Only ready tasks appear below. Refine other items in Task details.</p><fieldset class="work-dependencies"><legend>Sprint backlog</legend>${ready.map(t=>`<label><input type="checkbox" name="itemIds" value="${t.id}">${esc(t.title)} · ${t.points} pts</label>`).join('')||'<p>No ready tasks yet.</p>'}</fieldset>${area('note','Planning notes / readiness evidence','')}<footer>${button('close','Cancel')}<button class="primary" ${ready.length?'':'disabled'}>Start sprint</button></footer></form>`);
  }else if(action==='close_sprint')board.dialogShell('Review & close sprint',`<form class="work-item-form"><p>Verified Done items earn points. Unfinished work returns to the backlog with zero credit and must be selected again for a future sprint. The recorded review is retained.</p>${area('note','Sprint Review · demonstrated outcomes and evidence','',3)}${area('improvement','Retrospective · one improvement, owner, and follow-up','',3)}<footer>${button('close','Cancel')}<button class="primary">Close sprint</button></footer></form>`);
  else board.dialogShell('Review phase gate',`<form class="work-item-form"><h3>${esc(phases[f.phaseIndex])}</h3><p>Confirm the phase outputs and independent verification. Gate approval records a management decision; it does not execute or authorize production deployment.</p>${f.phaseIndex===0?area('scopeBaseline','Scope baseline',m.scopeBaseline)+area('scheduleBaseline','Schedule baseline',m.scheduleBaseline)+area('riskRegister','Risk register',m.riskRegister):''}${area('note','Gate evidence and sponsor decision','',4)}<footer>${button('close','Cancel')}<button class="primary">Approve gate</button></footer></form>`);
  const form=board.dialog.querySelector('form');for(const field of form.querySelectorAll('textarea'))field.required=true;
  form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const input=Object.fromEntries(new FormData(form));try{if(action==='start_sprint')input.schedule=readDates(form);}catch(error){board.error(error);return;}input.itemIds=[...form.querySelectorAll('[name=itemIds]:checked')].map(e=>e.value);board.working(async()=>{await board.api('work/delivery',{...input,action,project:board.project.path,planId:p.id,expectedRevision:p.revision});board.closeDialog();await board.refresh(true);}).catch(error=>board.error(error));});
}
export function reviewerDialog(board){
  const p=board.detail,m=p.management;
  board.dialogShell('Delegate task reviews',`<form class="work-item-form"><p>Select teammates who may review completed work alongside the QA lead. They must independently check the acceptance criteria and provide evidence. Owners and previous contributors remain ineligible for their own tasks.</p>${reviewerFields(board,p.participantIds,m.reviewerIds||[],m.qaLeadId)}<footer>${button('close','Cancel')}<button class="primary">Save reviewers</button></footer></form>`);
  const form=board.dialog.querySelector('form');
  form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();const reviewerIds=[...form.querySelectorAll('[name=reviewerIds]:checked')].map(input=>input.value);board.working(async()=>{await board.api('work/reviewers',{project:board.project.path,planId:p.id,expectedRevision:p.revision,reviewerIds});board.closeDialog();await board.refresh(true);}).catch(error=>board.error(error));});
}
export function verifyDialog(board,itemId){
  const p=board.detail,t=p.items.find(t=>t.id===itemId);
  board.dialogShell('Verify task',`<form class="work-item-form"><h3>${esc(t.title)}</h3><div class="work-brief-document">${documentNote('Acceptance',t.acceptance||p.acceptance||'See brief')}${documentNote('Definition of Done',p.management.definitionOfDone)}${documentNote('Owner’s evidence',t.note||'None provided')}</div><label>Decision<select name="passed"><option value="true">Verified · Mark Done</option><option value="false">Changes required · Return to owner</option></select></label>${area('evidence','Independent verification evidence','',4)}<footer>${button('close','Cancel')}<button class="primary">Save verification</button></footer></form>`);
  const form=board.dialog.querySelector('form');form.elements.evidence.required=true;
  form.addEventListener('submit',e=>{e.preventDefault();e.stopPropagation();board.working(async()=>{await board.api('work/verify',{project:board.project.path,planId:p.id,itemId,expectedRevision:p.revision,passed:form.elements.passed.value==='true',evidence:form.elements.evidence.value});board.closeDialog();await board.refresh(true);}).catch(error=>board.error(error));});
}
